// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Radioactivity".

Just some blast that expand from a direct top-down view, 
capturing the shapes and motions of the expanding gases. 

Interaction:
- Space Bar: Pause/Play
- Mouse Wheel: Forward / Backward in time

*/

const scale = Math.max(1, devicePixelRatio / 2)
let theShader, wheelDelta = 0, wheelOffset = 0, pause = false, paused = 0, time = 0

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2975280/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function mouseWheel(e) {
	if (wheelDelta * e.deltaY < 0) {
		wheelDelta = e.deltaY
	} else {
		wheelDelta = lerp(wheelDelta, e.deltaY, .05)
	}
	wheelOffset += wheelDelta
}

function keyPressed(e) {
	if (e.key === " ") {
		if (!pause) {
			pause = true
		} else {
			pause = false
			paused = millis() - time
		}
	}
}

function draw() {
  shader(theShader)
  if (!pause) time = millis() - paused
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("wheel", [wheelDelta, wheelOffset])
  theShader.setUniform("time", time / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 wheel;
#define FC gl_FragCoord.xy
#define R resolution
#define T (time+wheel.y/1e3)
#define S smoothstep
#define MN min(R.x,R.y)
#define hue(a) (.5+.5*sin(3.14*(a)+vec3(1,2,3)))
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
// white noise
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p*34.56);
	return fract(p.x*p.y);
}
// value noise
float noise(vec2 p) {
	vec2 i=floor(p), u=S(i,i+1.,p), k=vec2(1,0);
	float
	a=rnd(i),
	b=rnd(i+k),
	c=rnd(i+k.yx),
	d=rnd(i+k.xx);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
// fractional brownian motion
float fbm(vec2 p) {
	float t=.0, a=1.;
	for (int i; i++<5;) {
		t+=a*noise(p);
		p*=2.;
		a/=2.;
	}
	return t;
}
vec3 render(vec2 uv) {
	vec2 st=uv;
	vec3 col=vec3(0);
	uv*=rot(.78)*.5;
	uv.x-=1e-2*sin(st.y*.2-T);
	uv=vec2(1,exp(clamp(dot(uv,2.*uv+fbm(T*.5-uv+fbm(T*.1-st*8.+fbm(st*12.)))*.25-.325),.0,.25)));
	float k=fbm(12.-uv+fbm(23.-uv*4.+fbm(2.-uv*16.+fbm(uv*64.+rnd(st)))));
	col+=hue(.4+k*clamp(dot(uv,uv),.0,.25))+.5*k*k*hue(.4+12.*log(dot(uv,uv)));
	col.xz*=rot(length(vec2(atan(uv.x,uv.y),log(dot(uv,uv))-T)));
	col.yz*=rot(T*.2-dot(st,st));
	col=abs(col);
	col=S(-.5,.5,col)*.8;
	col=mix(mix(vec3(2,.4,.2),vec3(.7,.2,.1),col.r),vec3(1),col.g);
	col=tanh(col*col);
	col=S(.85,.2,sqrt(col));
	return col;
}
void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=render(uv);
	col=mix(vec3(0),col,pow(clamp(1.-dot(uv*.2,uv*.2),.0,1.),8.));
	O=vec4(col,1);
}

